async function downloaded(directory, beforeNames, format, expected) {
  for (let attempt = 0; attempt < 100; attempt++) {
    const names = (await readdir(directory)).filter(name => !beforeNames.includes(name) && name.endsWith('.' + format));
    for (const name of names) {const path = join(directory, name), bytes = await readFile(path); if (format === 'svg' && !bytes.equals(Buffer.from(expected.text))) continue; if (format === 'png' && (bytes.length !== expected.blobBytes || !bytes.subarray(0, 8).equals(Buffer.from([137,80,78,71,13,10,26,10])))) continue; return {path, bytes: bytes.length, sha256: hash(bytes), raw: bytes};}
    await new Promise(resolve => setTimeout(resolve, 50));
  }
  throw Error('No actual matching Canvas ' + format.toUpperCase() + ' download appeared in the owned directory');
}
