    // Zoom in control to reveal details, as the existing Canvas workflow does.
    let observed=receipt.afterFit;
    for(let step=0;step<40&&observed.viewport.details!=='visible';step++){
      const zoom={before:observed,after:null};receipt.zoom.push(zoom);await tools.click(action(id,'zoom-in'));zoom.after=await boardOpeningObservation(tools,id,path);observed=zoom.after;
    }
    receipt.beforePreview=await boardOpeningObservation(tools,id,path);
