  const receipt=await tools.evaluate('canvasExportConversionRetired.proof');assert.equal(receipt.currentRoot,true);assert.equal(receipt.owners.length,ids.length);for(const owner of receipt.owners)for(const [key,value]of Object.entries(owner.checks))assert.equal(value,true,label+': retired '+owner.path+' '+key);
